import {head,note,section,link,action,submit,stats,field,area,select,hero,empty,chips,body,fmt,duration,dateLabel,safe,icon} from './life-ui.js';
import {routineDone,sleepMinutes,nextStep,weightSummaryAt} from './personal-state.js';
import {latestSleep} from './me-pages.js';
const parts={reggel:'Reggel',nap:'Napközben',delutan:'Délután',este:'Este'};
const metricLabels={energy:'Energia',stress:'Stressz',body:'Testi jóllét',mind:'Mentális jóllét'};
export function dayPage(s,p,v,id,ui,e){
 if(!v)return [()=>today(s,ui,e),()=>conversation(s,ui,e),()=>routines(s,ui),()=>closing(s,e)][p]();
 if(v==='quick')return head('GYORS RÖGZÍTÉS','Mi érkezett?','Egy kis lépés, és máris a napod része.','bolt')+`<div class="lf-pair">${link('ring','Súly','Új mérés vagy pontosítás.','me/1/weight-log')}${link('moon','Alvás','Az éjszakád adatai.','me/2/sleep-log')}${link('heart','Check-in','Hogy vagy most?','nap/0/checkin')}${link('water','Víz','Egy pohárnyi figyelem.','nap/0/water')}${link('stack','Kiegészítők','A protokollod szerint.','fuel/3')}${link('bolt','Nehezebb nap','Csendes nézet, három horgony.','nap/0/rough')}</div><button class="lf-link" data-food>${icon('bowl')}<span><strong>Étkezés AI-értékeléssel</strong><small>Leírás → pontosítás → mentés.</small></span><b>↗</b></button><button class="lf-link" data-workout>${icon('dumbbell')}<span><strong>Mai edzés</strong><small>Indítás vagy folytatás.</small></span><b>↗</b></button>`+link('book','Gondolat, hála vagy döntés','A saját szavaiddal.','me/3/entry-new')+link('sun','Napi szándék','Amihez ma visszatérsz.','nap/0/intention');
 if(v==='rough')return rough(s,ui);
 if(v==='checkin')return checkins(s);
 if(v==='moment')return moment(s,id);
 if(v==='water')return water(s);
 if(v==='intention')return head('NAPI SZÁNDÉK','Egy mondatnyi irány.','Ami fontos, amikor a nap közben sokfelé húz.','sun')+hero('A MAI IRÁNYOD','', '',safe(s.intention||'Még nincs megadva.'),'sun')+`<form data-life-form="intention">${area('Ma erre szeretnék figyelni','text',s.intention)}${submit('Ez legyen ma az irány')}</form>`+section('Kapaszkodó, ha nehéz elkezdeni')+`<div class="lf-chips">${['Ma egy dolgot végigcsinálok.','Ma észreveszem, ha szünetre van szükségem.','Ma figyelmesen, nem sietve.'].map(t=>`<button data-life-intention="${t}">${t}</button>`).join('')}</div>`+note('A mintamondat csak az űrlapot tölti ki. A mentésed teszi a nap részévé.')+link('gem','A hosszabb távú céljaim','A napi irány ezekhez is kapcsolódhat.','me/0/goals');
 if(v==='signals')return signals(s,e);
 if(v==='timeline')return timeline(s,e);
 if(v==='context')return context(s,e);
 if(v==='thread')return thread(s,id,e);
 if(v==='history')return head('BESZÉLGETÉSEK','Itt tudjuk folytatni.','A mai témák és két korábbi mintabeszélgetés.','chat')+link('sun','A mai napom',s.messages.length+' saját üzenet a demóban.','nap/1')+link('moon','Szeptember 8. · Az edzés után','A pálya és a pihenés.','nap/1/thread/volley')+link('ring','Szeptember 7. · Vissza a ritmusba','A következő kicsi lépés.','nap/1/thread/rhythm');
 if(v==='briefing')return head('MEZO · NAPI ÁTTEKINTÉS','Ennyiből indulunk ma.','Előre megírt gondolat, az aktuális demóadatok mellett.','chat')+context(s,e,false)+section('A mai javaslat')+body('Az edzést és a pihenést együtt érdemes szem előtt tartani. Ha másképp vagy, mint reggel, előbb jelezd egy rövid check-inben. A terv utána is megvár.\nEz a demó nem elemez automatikusan: a javaslat mintaszöveg, a fölötte látható naplóadatok viszont frissülnek a mentéseiddel.')+link('heart','Hogy vagyok most?','Pótolható és pontosítható pillanatképek.','nap/0/checkin')+link('dumbbell','Ránézek a terhelésre','Gym és sport együtt.','train/1');
 if(v==='chain')return chain(s,id);
 if(v==='habit'){const r=s.routines.find(r=>r.id===id);return r?habit(s,r):missing();}
 if(v==='new')return habitForm(s);
 if(v==='routine-history')return head('RUTIN · VISSZATEKINTÉS','A visszatérés is ritmus.','Az elmúlt két hét szemléltető mintája és a mai tényleges demóállapot.','ring')+`<div class="lf-calendar">${Array.from({length:14},(_,i)=>`<div class="${[0,1,3,4,6,7,9,10,11].includes(i)?'filled':''}"><small>${i+27>31?i-4:i+27}</small><span>${i===13?s.routines.filter(r=>!r.paused&&routineDone(s,r)).length:[2,3,1,4,3,0,3,4,1,3,4,2,1][i]}</span></div>`).join('')}</div>`+note('A korábbi napok illusztrált darabszámok. A mai szám a saját demójelöléseidből és naplózásodból számolódik. Nincs elveszített sorozat vagy büntetés.')+link('ring','Vissza a mai rutinhoz','Innen bármikor folytathatod.','nap/2');
 if(v==='suggestion')return head('MEZO · RUTINÖTLET','Legyen könnyű elkezdeni.','Egy felvetés, amit a saját napodhoz igazíthatsz.','gem')+hero('MINTAJAVASLAT','1','perc','Ebéd után egy rövid szünet, mielőtt visszatérsz a következő feladathoz.','ring')+body('Miért ez? A mintanapban az ebéd és a délutáni edzés között van egy jól felismerhető átmenet. Ehhez könnyebb egy kicsi lépést kapcsolni, mint egy teljesen új időpontot kitalálni.\nA saját nevedet, kapaszkodódat és napszakodat te adod meg. Csak a mentés hozza létre a szokást.')+action('Saját szokást készítek belőle','nap/2/new')+link('gem','A céljaim felől nézem','Miért lenne ez fontos nekem?','me/0/goals');
 if(v==='close-edit')return closeForm(s);
 if(v==='close-summary')return closeSummary(s,e);
 if(v==='tomorrow')return head('HOLNAPI KAPASZKODÓ','Nem kell ma megoldanod.','Csak legyen egy helye annak, amit továbbvinnél.','sun')+body(s.closing?.tomorrow||'Még nincs holnapra megőrzött gondolat.')+link('moon','Napzárás pontosítása','A holnapi gondolatodat is itt alakíthatod.','nap/3/close-edit')+link('gem','A saját irányaim','Ha a gondolat hosszabb távra szól.','me/0/goals')+note('Ez nem hoz létre automatikusan holnapi szándékot, emlékeztetőt vagy naptáreseményt.');
 return missing();
}
function today(s,ui,e){const sl=latestSleep(s),water=s.water.reduce((n,r)=>n+r.ml,0),active=s.routines.filter(r=>!r.paused),done=active.filter(r=>routineDone(s,r)).length;
 // Az „egy kiemelt lépés": a hat csempe stabil, csak ez a blokk (és a köszöntés) él a napszakkal.
 const step=nextStep(s,ui.part,e);
 const ws=weightSummaryAt(s,s.date);
 const trend=ws.latest&&ws.average!=null&&ws.previous!=null&&ws.average!==ws.previous?(ws.average<ws.previous?' ↘':' ↗'):'';
 const morningContext=ui.part==='reggel'?`<div class="lf-day-context">${ws.latest?`<button data-life="me/1">Súly <b>${fmt(ws.latest.kg)} kg${trend}</b></button>`:''}${s.intention?`<button data-life="nap/0/intention">Fókusz <b>${safe(s.intention)}</b></button>`:''}</div>`:'';
 const lastOwnWater=s.water.at(-1)&&!s.water.at(-1).seed;
 const eveningStrip=ui.part==='este'?stats([[fmt(e.food.kcal,0)+' kcal',e.food.kcal<=2400?'kereten belül ✓':'kereten túl'],[e.workout.complete?'Megvolt ✓':'—','a mai mozgás'],['+'+(e.workout.xp||0)+' XP','a mai termés']])+link('moon','Csendes éjszakai felület','Egy sötétebb, nyugodt nézet lefekvéshez.','me/2/night'):'';
 return morningContext+`<button class="lf-next" data-life="${step.path}"><span class="overline">A KÖVETKEZŐ KIS LÉPÉS</span>${icon(step.icon)}<h2>${step.title}</h2><p>${safe(step.sub)}</p><b>Megnézzük együtt ↗</b></button><div class="lf-dashboard"><div class="lf-tile water" role="button" tabindex="0" data-life="nap/0/water" aria-label="Hidratáció · részletek"><span>Hidratáció</span><button class="lf-quick" data-life-water="250" aria-label="Egy pohár víz rögzítése · +250 ml">＋</button>${icon('water')}<strong>${fmt(water/1000,2)}<small> liter</small></strong><p>${lastOwnWater?'':'Koppints a ＋ jelre: +2,5 dl'}</p>${lastOwnWater?'<button class="lf-undo" data-life-water-undo>Utolsó pohár visszavonása</button>':''}<i style="--fill:${Math.min(100,water/20)}%"></i></div><button class="lf-tile sleep" data-life="me/2"><span>Az éjszakád</span>${icon('moon')}<strong>${sl?Math.floor(sleepMinutes(sl)/60):'—'}<small>${sl?' ó '+Math.round(sleepMinutes(sl)%60)+' p':''}</small></strong><p>${sl?'Minőség · '+sl.quality+'/10':'Még nincs naplózva'}</p></button><button class="lf-tile food" data-life="fuel/0"><span>Táplálkozás</span>${icon('bowl')}<strong>${fmt(2400-e.food.kcal,0)}<small> kcal maradt</small></strong><p>${fmt(e.food.p)} g fehérje eddig${ui.part==='nap'?' · Logold, ha ettél ↗':''}</p><i style="--fill:${Math.min(100,e.food.kcal/24)}%"></i></button><button class="lf-tile training" data-life="train/0"><span>Mai mozgás</span>${icon('dumbbell')}<strong class="word">${e.workout.complete?'Megcsináltad':'Felsőtest A'}</strong><p>${e.workout.complete?'Lezárt mintagym':'3 gyakorlat · 9 szett'}</p></button><button class="lf-tile routine" data-life="nap/2"><span>A rutinod</span>${icon('ring')}<strong>${done}<small> / ${active.length}</small></strong><p>A saját ritmusodban</p><i style="--fill:${active.length?done/active.length*100:0}%"></i></button><button class="lf-tile journal" data-life="me/3"><span>A saját szavaiddal</span>${icon('book')}<strong class="word">${s.entries.some(x=>x.date===s.date&&!x.archived)?'Megőrizve':'Egy gondolat'}</strong><p>${s.entries.filter(x=>x.date===s.date&&!x.archived).length} bejegyzés ma</p></button></div>`+eveningStrip+link('chat','Beszéljük át a napod','Mezo innen már látja a demóban rögzített jeleket.','nap/1')+section('A napod szálai')+link('heart','Életjelek','Saját jelzések és naplózott adatok.','nap/0/signals')+link('sun','A mai szándékod',safe(s.intention),'nap/0/intention')+link('book','A nap idővonala','Mi került már a helyére?','nap/0/timeline')+link('chat','Mezo napi áttekintése','Források és következő lépés.','nap/0/briefing')+`<button class="lf-rough-door" data-life="nap/0/rough">Nehezebb ma? Van egy csendesebb nézet is ›</button>`;}
function rough(s,ui){const anchors=[['viz','water','Egy pohár víz','Most. Egyszerű kezdet.'],['etkezes','bowl','Egy fehérje-étkezés','Bármi. Ennyi ma elég.'],['seta','sun','10 perc séta','Friss levegő. Nem futás.']];return head('NEHEZEBB NAP','Ma elég a minimum.','Itt vagyok. Három apró horgony, semmi több.','heart')+anchors.map(([id,art,title,sub])=>{const done=ui.anchors.has(id);return `<div class="lf-habit-row"><button class="lf-tick" data-life-anchor="${id}" aria-pressed="${done}" aria-label="${title} · ${done?'visszavonás':'megvolt'}">${done?'✓':'○'}</button><span class="lf-habit-title">${icon(art)}</span><span class="lf-habit-title"><strong>${title}</strong><small>${sub}</small></span></div>`;}).join('')+note('A horgonyok csak erre a nézetre szólnak; nem lesz belőlük elvárás vagy sorozat. A többi funkció megvár.')+action('Vissza a teljes naphoz','nap/0',true);}
function checkins(s){return head('CHECK-IN','Hogy vagy, tényleg?','Négy pillanatkép. Egyik sem osztályzat.','heart')+stats([[Object.keys(s.moments).length+'/4','mai pillanat'],['pótolható','a kimaradt is']])+Object.entries(parts).map(([id,label])=>{const m=s.moments[id];return `<div class="lf-moment"><span class="overline">${label}</span>${m?`<div class="lf-moment-values">${Object.entries(metricLabels).map(([k,l])=>`<span><strong>${m[k]}</strong><small>${l}</small></span>`).join('')}</div><p>${safe(m.note||'Nem írtál megjegyzést.')}</p>`:'<h2>Még nyitva hagytuk.</h2><p>Ha van kedved, megállhatsz egy pillanatra.</p>'}${action(m?'Pontosítom ezt a pillanatot':'Kitöltöm · '+label,'nap/0/moment/'+id,true)}</div>`;}).join('')+note('A stressznél a magasabb szám több stresszt jelent. Nem átlagoljuk össze a négy jelzést egy jólléti osztályzattá.');}
function moment(s,id){if(!parts[id])return missing();const m=s.moments[id]||{energy:6,stress:4,body:6,mind:6,note:''};return head('CHECK-IN · '+parts[id],'Most így vagyok.','Ami a számok mögött van, azt le is írhatod.','heart')+`<form data-life-form="moment" data-id="${id}">${Object.entries(metricLabels).map(([k,l])=>`<label class="lf-range"><span>${l}<output data-life-output="${k}">${m[k]} / 10</output></span><input name="${k}" aria-label="${l}" type="range" min="1" max="10" value="${m[k]}" data-life-range="${k}"><small>${k==='stress'?'1 · alig van jelen — 10 · nagyon erős':'1 · nagyon alacsony — 10 · nagyon jó'}</small></label>`).join('')}${area('Ami még fontos','note',m.note)}${submit(s.moments[id]?'Pillanat pontosítása':'Így vagyok most')}</form>`+action('Most kihagyom','nap/0/checkin',true);}
function water(s){const total=s.water.reduce((n,r)=>n+r.ml,0);return head('HIDRATÁCIÓ','Egy pohárnyi figyelem.','A napi folyadékbeviteled egyszerű naplója.','water')+hero('MA RÖGZÍTVE',fmt(total/1000,2),'liter','A poharakból áll össze a nap.','water')+`<div class="lf-chips">${[150,250,500].map(ml=>`<button data-life-water="${ml}">+${ml} ml</button>`).join('')}</div><form data-life-form="water">${field('Más mennyiség (ml)','ml',250,'number','min="50" max="1500" step="50" required')}${submit('Hozzáadom')}</form>`+section('A mai poharaid')+s.water.map(r=>`<div class="lf-timeline-item"><span>${r.time}</span><strong>${r.ml} ml</strong>${r.seed?'<small>mintaelőzmény</small>':''}</div>`).join('')+`<button class="lf-action secondary" data-life-water-undo ${s.water.at(-1)?.seed?'disabled':''}>Utolsó saját pohár visszavonása</button>`+note('A 2 literes kezdőlapi sáv vizuális demóérték, nem személyre szabott folyadékajánlás.');}
function signals(s,e){const m=s.moments.este||s.moments.delutan||s.moments.nap||s.moments.reggel,sl=latestSleep(s);return head('ÉLETJELEK','Mire érdemes figyelni?','Naplózott adatok és saját jelzések, közös osztályzat nélkül.','heart')+`<div class="lf-context-grid">${link('heart','Energia',m?m.energy+'/10 · legutóbbi saját jelzés':'Még nincs jelzés','nap/0/checkin')}${link('water','Víz',fmt(s.water.reduce((n,r)=>n+r.ml,0)/1000,2)+' liter · ma','nap/0/water')}${link('moon','Pihenés',sl?duration(sleepMinutes(sl)):'Még nincs éjszaka','me/2')}${link('dumbbell','Mozgás',e.workout.complete?'Mai gym lezárva':'Mai gym terv','train/0')}${link('heart','Belső állapot',m?m.mind+'/10 · saját jelzés':'Még nincs jelzés','nap/0/checkin')}${link('ring','Ritmus',s.routines.filter(r=>!r.paused&&routineDone(s,r)).length+' mai lépés teljesült','nap/2')}</div>`+note('A hiányzó jelzés üres marad. A testi és mentális megélésedet nem helyettesítjük automatikus következtetéssel.')+link('chat','Beszéljünk róla','A saját megélésed ad értelmet a számoknak.','nap/1');}
function timeline(s,e){const sl=s.sleeps.find(x=>x.date===s.date);return head('A NAP IDŐVONALA','Ami már megérkezett.','A mai demó naplózásai, egy közös történetben.','book')+(sl?link('moon',sl.wake.slice(11)+' · Ébredés',duration(sleepMinutes(sl))+' naplózott alvás','me/2/sleep-night/'+s.date):'')+Object.entries(s.moments).map(([id,m])=>link('heart',parts[id]+' · Check-in','Energia '+m.energy+'/10 · stressz '+m.stress+'/10','nap/0/moment/'+id)).join('')+link('water',s.water.length+' pohárnyi víz',fmt(s.water.reduce((n,r)=>n+r.ml,0)/1000,2)+' liter rögzítve','nap/0/water')+link('bowl','Étkezések',fmt(e.food.kcal,0)+' kcal naplózva','fuel/0')+link('dumbbell',e.workout.complete?'Edzés lezárva':'Edzés · még nyitott',e.workout.complete?'A logolt szettek már a terhelés részei.':'A terv nem számít elvégzett edzésnek.','train/0')+s.entries.filter(x=>x.date===s.date&&!x.archived).map(x=>link('book','Saját bejegyzés',safe(x.text.slice(0,80)),'me/3/entry/'+x.id)).join('')+(s.closing?link('moon','Napzárás','A mai nap a helyén.','nap/3/close-summary'):'')+note('Az időpont nélküli eseményeket csoportosan mutatjuk; nem találunk ki hozzájuk pontos időt.');}
function context(s,e,heading=true){const sl=latestSleep(s),m=s.moments.este||s.moments.delutan||s.moments.nap||s.moments.reggel;return (heading?head('A BESZÉLGETÉS KIINDULÓPONTJA','Tudod, miből indulok.','A naplózott tény és Mezo értelmezése külön látszik.','stack'):'')+section('A naplóidból')+stats([[sl?duration(sleepMinutes(sl)):'—','utolsó alvás'],[fmt(e.food.kcal,0)+' kcal','mai étkezés']])+link('heart','A legutóbbi pillanatod',m?'Energia '+m.energy+'/10 · stressz '+m.stress+'/10':'Még nincs check-in','nap/0/checkin')+link('dumbbell','Mai edzés',e.workout.complete?'Lezárt mintagym':'Felsőtest A · terv vagy folyamatban','train/0')+section('Amit te mondtál')+body('Mai szándék: '+s.intention)+s.goals.filter(g=>g.status==='active').map(g=>link('gem',safe(g.title),safe(g.step),'me/0/goal/'+g.id)).join('')+section('Értelmezések, amiket javíthatsz')+link('person','Mezo rólad alkotott képe','A karakterállítások nem naplózott tények.','mezo/2')+link('gem','Amit együtt figyelünk','Felfedezések és korlátaik.','mezo/0')+link('stack','Megőrzött tudás','Eredet és felhasználhatóság.','mezo/3')+note('A demó a beszélgetés mellett megmutatja ezeket a forrásokat. Nem állít össze valódi system promptot és nem küldi el őket modellnek.');}
export function conversationRows(s){return s.messages.map((m,i)=>`<div class="lf-chat-user"><span>TE</span><p>${safe(m.text)}</p></div><div class="lf-chat-mezo"><span>MEZO · DEMÓVÁLASZ</span><p>${safe(m.reply)}</p>${m.path?action(m.label,m.path,true):''}<button class="lf-chat-save" data-life-save-message="${i}" ${m.saved?'disabled':''}>${m.saved?'Naplóban megőrizve ✓':'A saját mondatomat a naplóba mentem ↗'}</button></div>`).join('');}
function conversation(s,ui,e){return head('MEZO · MAI BESZÉLGETÉS','Itt már van előzményünk.','Kezdhetjük azzal, ami most foglalkoztat.','chat')+link('stack','Miből indulok ki?','Mai naplók, célok és javítható értelmezések.','nap/1/context')+`<div class="lf-chat-mezo"><span>MEZO · MINTANYITÁS</span><p>${latestSleep(s)?'Az éjszakád már itt van. ':''}${e.workout.complete?'A mai edzést lezártad.':'A mai edzésed még a nap része.'} Arról beszéljünk, mi fér bele, vagy arról, hogy vagy?</p></div><div id="life-chat-history">${conversationRows(s)}</div><div class="lf-chips">${['Fáradtnak érzem magam.','Hogy férjen bele ma az edzés?','Szeretném letenni a napot.'].map(t=>`<button data-life-prompt="${t}">${t}</button>`).join('')}</div><form data-life-form="chat">${area('Üzenet Mezonak','text',ui.chatDraft,'Ami most benned van…')}${submit('Elküldöm a demóbeszélgetésbe')}</form>`+note('Kipróbálható beszélgetés, előre megírt válaszokkal. Szabad szövegre is csak a demó korlátozott válaszai érkeznek; nincs valódi AI-hívás.')+link('book','Korábbi beszélgetések','A mai és két korábbi mintaszál.','nap/1/history')+link('book','Inkább csak leírom','Új naplóbejegyzés.','me/3/entry-new');}
function thread(s,id,e){const volley=id==='volley';if(!volley&&id!=='rhythm')return missing();return head('KORÁBBI MINTABESZÉLGETÉS',volley?'A pálya után.':'Vissza a ritmusba.',volley?'Szeptember 8. · kedd':'Szeptember 7. · hétfő','chat')+`<div class="lf-chat-user"><span>TE · MINTA</span><p>${volley?'Jó volt a röplabda, de érzem a vállam.':'Túl sok mindent próbálok egyszerre visszaépíteni.'}</p></div><div class="lf-chat-mezo"><span>MEZO · MINTA</span><p>${volley?'A megélt terhelést és a következő gym napot együtt tudjuk nézni. Mit rögzítettél az edzésről?':'Melyik lenne az az egy apró lépés, amihez könnyű lenne visszatérni?'}</p></div>`+link(volley?'dumbbell':'ring',volley?'Kapcsolódó terhelés':'Kapcsolódó rutin',volley?'Gym és sport együtt.':'Egy tartható kapaszkodó.',volley?'train/1':'nap/2')+action('A mai beszélgetésben folytatom','nap/1');}
function routines(s,ui){const active=s.routines.filter(r=>!r.paused),done=active.filter(r=>routineDone(s,r)).length;return head('RUTIN','Ami megtart a napban.','Apró lépések. A saját sorrendedben.','ring')+hero('MAI LÉPÉSEK',done,'/ '+active.length,'A kihagyott lépés után is visszatérhetsz.','ring')+['reggel','nap','este'].map(part=>{const rows=active.filter(r=>r.part===part);return link(part==='este'?'moon':'sun',parts[part],rows.filter(r=>routineDone(s,r)).length+' / '+rows.length+' lépés · '+rows.map(r=>safe(r.name)).join(' · '),'nap/2/chain/'+part);}).join('')+action('Új saját szokás','nap/2/new')+link('gem','Mezo egy ötlete','Egy felvetésből saját lépés lehet.','nap/2/suggestion')+link('book','Ahogy visszatérsz','Kéthetes szemléltető ritmus.','nap/2/routine-history')+(s.routines.some(r=>r.paused)?section('Most pihennek')+s.routines.filter(r=>r.paused).map(r=>link('ring',safe(r.name),'Szüneteltetve · bármikor folytatható','nap/2/habit/'+r.id)).join(''):'');}
function chain(s,id){if(!['reggel','nap','este'].includes(id))return missing();const rows=s.routines.filter(r=>r.part===id&&!r.paused);return head('RUTIN · '+parts[id],id==='este'?'Lassan elengedheted.':id==='reggel'?'Induljunk könnyedén.':'Legyen egy kis tér.','A lépéseket egyenként is megnyithatod.','ring')+rows.map(r=>`<div class="lf-habit-row"><button class="lf-tick" ${r.derived?`data-life="${r.derived==='sleep'?'me/2/sleep-log':'nap/0/intention'}"`:`data-life-habit="${r.id}" aria-pressed="${routineDone(s,r)}"`} aria-label="${safe(r.name)} · ${r.derived?'napló megnyitása':routineDone(s,r)?'teljesítés visszavonása':'teljesítés'}">${routineDone(s,r)?'✓':'○'}</button><button class="lf-habit-title" data-life="nap/2/habit/${r.id}"><strong>${safe(r.name)}</strong><small>${r.derived?'A naplózásodból teljesül':safe(r.anchor)}</small></button><span>↗</span></div>`).join('')+(!rows.length?empty('Itt most nincs aktív lépés.','Választhatsz egy kicsi saját szokást.','nap/2/new','Új szokás'):'')+note('A kézzel jelölhető lépés visszavonható. Az alvás és a szándék a tényleges demóadatból teljesül, nem pipálható ki helyettük.')+action('Saját lépést adok hozzá','nap/2/new',true);}
function habit(s,r){return head('SZOKÁS · '+parts[r.part],safe(r.name),r.paused?'Most szünetel.':routineDone(s,r)?'Ma már megvan.':'Van még helye a napban.','ring')+section('A kapaszkodód')+body(r.anchor)+section('Miért csinálod?')+body(r.why)+(r.derived?link(r.derived==='sleep'?'moon':'sun','A kapcsolódó napló megnyitása','Ebből teljesül ez a lépés.',r.derived==='sleep'?'me/2/sleep-log':'nap/0/intention'):`<button class="lf-action" data-life-habit="${r.id}" ${r.paused?'disabled':''}>${r.done?'Teljesítés visszavonása':'Ma megtettem ✓'}</button>`)+`<button class="lf-action secondary" data-life-pause="${r.id}">${r.paused?'Újra folytatom':'Egy időre szüneteltetem'}</button>`+(!r.derived?habitForm(s,r):note('Az automatikusan teljesülő alaplépés szabályát nem írjuk át kézzel. Szüneteltetni ezt is lehet.'));}
function habitForm(s,r){return (!r?head('ÚJ SZOKÁS','Egy kicsi, saját lépés.','Legyen neve, helye a napodban és egy könnyű kapaszkodója.','ring'):section('A saját napomhoz igazítom'))+`<form data-life-form="habit" data-id="${r?.id||''}">${field('A szokás neve','name',r?.name||'','text','maxlength="100" required')}${select('Mikor legyen helye?','part',[['reggel','Reggel'],['nap','Napközben'],['este','Este']],r?.part||'nap')}${field('Mi után következzen?','anchor',r?.anchor||'','text','maxlength="160" placeholder="Pl. az ebéd után" required')}${area('Miért fontos nekem?','why',r?.why||'')}${submit(r?'Szokás pontosítása':'Ezt a lépést vállalom')}</form>`;}
function closing(s,e){return head('NAPZÁRÁS',s.closing?'A mai nap a helyén.':'Mára ennyi is elég.','Nem értékelünk le. Megnézzük, mit vinnél magaddal.','moon')+`<div class="lf-closing-orbit" aria-hidden="true">${icon('moon')}<i></i><b></b></div>`+stats([[s.entries.filter(x=>x.date===s.date&&!x.archived).length,'mai bejegyzés'],[Object.keys(s.moments).length,'saját pillanat'],[s.routines.filter(r=>!r.paused&&routineDone(s,r)).length,'megtett lépés']])+action(s.closing?'Visszanézem a lezárásomat':'Leteszem a napot',s.closing?'nap/3/close-summary':'nap/3/close-edit')+link('book','Mi történt ma?','A naplózott események közös idővonala.','nap/0/timeline')+link('heart','Még jeleznék magamról','Az esti pillanatkép.','nap/0/moment/este')+link('ring','Esti rutin','Ami segít megérkezni.','nap/2/chain/este')+link('moon','Csendes éjszakai felület','Egy sötétebb, nyugodt nézet.','me/2/night');}
function closeForm(s){return head('ESTI VISSZATEKINTÉS','Ami marad. Ami mehet.','Egyik mező sem kötelező. Csendben is lezárhatod a napot.','moon')+`<form data-life-form="close">${area('Ezt magammal viszem','keep',s.closing?.keep||'','Egy pillanat, egy ember, valami jó…')}${area('Ezt most leteszem','release',s.closing?.release||'','Ami már ráér…')}${area('Holnapra egy kapaszkodó','tomorrow',s.closing?.tomorrow||'','Nem feladatlista. Egyetlen gondolat.')}${submit(s.closing?'Napzárás pontosítása':'Mára lezárom')}</form>`+note('A leírt gondolatok egyetlen szerkeszthető naplóbejegyzésbe kerülnek. A csendes lezárás nem készít üres bejegyzést.')+action('Még visszamegyek','nap/3',true);}
function closeSummary(s,e){if(!s.closing)return empty('Még nem zártad le a napot.','A saját tempódban érkezhetsz meg.','nap/3/close-edit','Leteszem a napot');return head('NAPZÁRÁS · MEGŐRIZVE','A többi ráér holnap.','A saját szavaidban hagytuk meg a napodat.','moon')+[['Magammal viszem',s.closing.keep],['Leteszem',s.closing.release],['Holnapi kapaszkodó',s.closing.tomorrow]].map(([l,t])=>section(l)+(t?body(t):note('Ezt most csendben hagytad.'))).join('')+(s.entries.some(x=>x.id==='day-close')?link('book','Megőrzött naplóbejegyzés','Az esti gondolataid egy helyen.','me/3/entry/day-close'):'')+action('Jöhet a pihenés','me/2/night')+action('Még pontosítanék rajta','nap/3/close-edit',true)+link('sun','Amit holnapra hagytál','Nem lett belőle automatikusan új feladat.','nap/3/tomorrow');}
function missing(){return empty('Ez az oldal nem található.','Az alsó menüből folytathatod.','nap/0','Vissza a mai naphoz');}
